var RULES_DATA=[{"title": "99", "spelers": null, "benodigdheden": ["Een spel kaarten"], "glas": "8 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  Elke speler heeft te allen tijde vier kaarten in zijn/haar hand. Op tafel ligt een gesloten stapel.", "2.  De waarde, die op de kaarten staat, is de waarde voor het spel. De plaatjes zijn tien punten.", "3.  De speler, die begint, legt een kaart open op tafel. Dit is de eerste kaart van de stapel. Hij/zij noemt dan de waarde van de kaart. Hij/zij pakt dan een kaart van de gesloten stapel, zodat hij/zij weer vier kaarten in zijn/haar hand heeft.", "4.  De beurt schuift met de klok mee door.", "5.  Dan legt de speler links van de beginnende speler een kaart op de open stapel en noemt nu de totale waarde van de stapel op.", "Voorbeeld: Speler A begint en legt 7 op. Hij zegt: ‘Zeven.’ Speler B legt daarna 5 op, zij zegt: ‘Twaalf.’", "I.  Als een speler de totale waarde van de stapel fout heeft, moet hij/zij een slok drinken.", "6.  Zo gaat de ronde door tot de stapel in totaal een waarde heeft van méér dan 99. De speler, die met zijn/haar kaart over de totale waarde van 99 gaat, heeft verloren en moet een (half) adtje trekken."]}, {"kop": "Bijzondere regels", "regels": ["1.  De Aas is 1 of 11 punten. Dat mag de speler, die hem opgooit, zelf bepalen.", "2.  De Koning is 0 punten. De speler, die hem oplegt, mag een medespeler aanwijzen die een half adtje moet trekken. Heeft deze speler echter zelf ook een koning, dan mag hij/zij hem meteen opleggen en moet de eerste speler een adtje trekken.", "Voorbeeld: Speler C legt de K op. Hij wijst Speler D aan, maar Speler D legt de K op. Speler C moet nu een heel adtje trekken.", "3.  Een tien is ofwel tien punten erbij, ofwel tien punten eraf. Dat mag de speler, die hem opgooit, zelf bepalen.", "4.  Een vier heeft de waarde vier. Als je een vier opgooit, word jij bij de volgende ronde overgeslagen en mag je zelf geen kaart opgooien.", "Hint: Gebruik deze kaart aan het einde van de ronde…"]}], "pullen": [1, 0, 0.5]}, {"title": "Fuck the Dealer", "spelers": null, "benodigdheden": ["Een spel kaarten"], "glas": "8 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  Eén speler is de dealer. Deze heeft de stapel kaarten.", "2.  Een andere speler noemt een waarde van een kaart.", "3.  De dealer geeft aan of de bovenste kaart van de stapel inderdaad die waarde heeft.", "I.  Heeft de speler de kaart niet goed, dan geeft de dealer aan of de bovenste kaart hoger of lager is dan de genoemde kaart (de Aas is hoog);", "II. Heeft de speler in eerste instantie de kaart wel goed, dan moet de dealer twee slokken drinken.", "4.  Als de speler in eerste instantie de waarde fout had, noemt deze nu opnieuw een waarde van een kaart.", "I.  Heeft de speler de kaart goed, dan moet de dealer één slok drinken;", "II. Heeft de speler de kaart niet goed, dan moet de speler één slok drinken. De speler links van hem/haar dan is aan de beurt.", "5.  De dealer laat nu de kaart zien en legt deze open op tafel. De kaarten worden op waarde gesorteerd. Kaarten met dezelfde waarden worden gestapeld.", "6.  Wanneer er drie spelers achter elkaar hebben verloren en moeten drinken, verandert de dealer. De speler links van de dealer wordt dan de nieuwe dealer."]}], "pullen": [0, 1, 1]}, {"title": "Kaartje Blazen", "spelers": null, "benodigdheden": ["Een spel kaarten", "Een glas, bij voorkeur een buikje"], "glas": "8 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  De kaarten worden op één stapel op het glas gelegd.", "2.  Elke speler, die aan de beurt is, moet door middel van blazen minimaal één kaart van het glas blazen. Dit moet hij/zij doen in één ademteug.", "I.  Lukt het de speler niet om één kaart van de stapel af te blazen, moet hij/zij één slok nemen. De beurt is pas voorbij als er een kaart vanaf is geblazen;", "II. Stoot de speler tijdens de beurt een kaart van het glas of raakt hij/zij een kaart aan, moet hij/zij eerst een slok drinken alvorens hij/zij door mag gaan.", "3.  De beurt gaat met de klok mee rond.", "4.  De speler, die de laatste kaart van het glas blaast/tikt, heeft verloren en moet een (half) adtje trekken.", "5.  De verliezer mag dan de kaarten schudden en op het glas leggen zoals hij/zij wilt, zolang alle kaarten maar op het glas liggen."]}, {"kop": "Variërende regel (zelf af te spreken)", "regels": ["1.  Normaal gesproken mag een speler niet gehinderd worden tijden het blazen. Er kan echter worden afgesproken dat dit wel toegestaan is."]}], "pullen": [1, 0, 0.5]}, {"title": "Kingsen", "spelers": null, "benodigdheden": ["Een spel kaarten", "Een glas"], "glas": "8 slokken", "secties": [{"kop": "Verloop van het spel", "regels": ["1.  Er wordt een cirkel van kaarten gemaakt om het glas heen.", "2.  Elke speler trekt om beurten een kaart uit de cirkel. De kaart, die hij/zij trekt, geeft het spel aan dat wordt gespeeld.", "3.  De beurt verschuift met de klok mee.", "4.  Het is belangrijk dat bij het trekken van de kaarten de cirkel rondom het glas niet wordt verbroken. Wordt de cirkel door een speler verbroken, dan moet die speler een adtje trekken. Het maakt daarna niet meer uit of de cirkel opnieuw doorbroken wordt."]}, {"kop": "Spelregels", "regels": ["De volgende regels zijn een voorbeeld, andere regels kunnen ook worden bedacht:", "2.  Zwart/Rood. Wanneer deze kaart een zwarte twee is, mag je twee slokken uitdelen. Wanneer deze kaart een rode twee is, moet je twee slokken drinken.", "3.  Waterval. Elke speler zet zijn/haar glas aan de mond. Als de speler, die de kaart trok, begint met drinken, begint ook de rest met drinken. De speler, die de kaart trok, mag beslissen wanneer hij/zij ophoudt met drinken. De rest drinkt door. Als de speler, die de kaart trok, is opgehouden met drinken, mag de speler links beslissen wanneer hij/zij ophoudt met drinken, enz.", "4.  Fours, whores. De vrouwen moeten een slok nemen.", "5.  Snake eyes. De speler, die deze kaart heeft getrokken, mag niet in de ogen worden aangekeken. Doet iemand dat wel, dan moet die speler een slok drinken.", "6.  Six, dicks. De mannen moeten een slok nemen.", "7.  Juffen. Hierbij wordt door de spelers geteld. Bij het tellen mogen geen getallen met een 7 erin (7, 17, 27, etc.) of meervouden van 7 (7, 14 ,21, etc.) worden gezegd. Wanneer men bij zo’n getal is aangekomen, zegt die speler iets willekeurigs of ‘Juf.’ De speler die als eerste een fout maakt, moet een slok drinken.", "8.  Plaskaart. Met deze kaart mag je één keer de tafel verlaten.", "Hint: Deze kaart kan je ook verkopen…", "9.  Nine, bust a rhyme. De speler, die deze kaart trekt, mag een zin zeggen. De volgende spelers moeten dan een zin zeggen die daarop rijmt. De speler die geen rijmwoord meer weet of die een al gebruikt rijmwoord noemt, moet een slok drinken.", "10. Houding. De speler, die deze kaart trekt, mag één keer in het spel een houding aannemen. De speler, die op dat moment de houding als laatste aanneemt, moet een slik drinken.", "J. Jack of categories. De speler, die deze kaart trekt, noemt een productsoort (bijv. bier), hij/zij begint met het eerste merk. De speler, die als eerste geen merknaam meer kan noemen of een al gebruikte merknaam noemt, moet een slok drinken.", "Q.  Question Queen. Als een speler deze kaart trekt, mag geen andere speler een vraag van hem/haar beantwoorden. Doet hij/zij dat wel, moet hij/zij een slok drinken. Als je op de vraag van de Question Queen met een wedervraag reageert, hoef je niet te drinken. Beantwoordt de Question Queen een vraag dan moet hij/zij drinken.", "K.  Koningsadtje. Bij de eerste drie koningen, die worden getrokken, mag het glas in het midden worden gevuld, met wat die speler wilt. De speler, die de laatste koning trekt, moet dit glas leegdrinken. Het spel is hierna afgelopen.", "A.  Regel. De speler, die deze kaart trekt, mag een willekeurige regel bedenken, die voor de rest van het spel blijft gelden."]}], "pullen": [1, 0, 0]}, {"title": "Magic Bussen", "spelers": null, "benodigdheden": ["Een spel kaarten"], "glas": "8 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  In de eerste fase van het spel worden, met de klok mee, aan elke speler vier kaarten gedeeld. Voordat hij/zij een kaart krijgt, moet de speler het volgende over de kaart zeggen, respectievelijk:", "I.  Rood of zwart: is de kaart een rode of zwarte kaart?", "II. Hoger of lager: is de kaart hoger of lager dan de eerste kaart (de Aas is hoog)?", "III. Binnen of buiten: valt de kaart tussen de twee eerste kaarten in, op het gebied van waarde, of daarbuiten?", "IV. Soort: van welke soort is de kaart, oftewel is de vierde kaart een harten, schoppen, ruiten of klaveren?", "Wanneer je een vraag fout hebt, moet je zelf drinken. Als je een vraag goed hebt, mag je een slok uitdelen.", "2.  Wanneer iedereen de vier kaarten heeft gekregen, blijven de kaarten open voor de speler op tafel liggen. Met de overige kaarten wordt een veld van gesloten kaarten uitgelegd, zoals hieronder aangegeven:", "3.  Er wordt linksboven begonnen met de kaarten om te draaien, dan de kaart eronder, daarna de bovenste kaart van de tweede kolom, en zo verder.", "I.  Wanneer een speler een kaart uit de bovenste rij voor zich heeft liggen, mag hij uitdelen;", "II. Wanneer een speler een kaart uit de onderste rij voor zich heeft liggen, moet hij zelf drinken;", "III. Bij de eerste kolom gaat het om één slok, bij de tweede kolom om twee slokken, etc..", "4.  Wanneer een speler de laatste, meest rechtse, kaart voor zich heeft liggen, zit hij/zij zogenaamd ‘in de bus.’ Deze speler(s) moeten(en) de laatste fase van het spel spelen.", "5.  Voor de laatste fase van het spel worden alle kaarten weer ingenomen. Het volgende veld wordt daarna uitgelegd:", "6.  De speler(s) die in de bus zit(ten), moet(en) het veld van de ene kant naar de andere kant doorkruizen, het maakt niet uit of de speler links of rechts begint.", "7.  De speler in de bus, wijst een kaart aan. Als het geen plaatje is, schuift hij/zij een kolom op. De volgende kaart moet grenzen aan de vorige kaart.", "Voorbeeld:", "8.  Als er een plaatje omgedraaid wordt, moet(en) de speler(s) opnieuw beginnen en wordt er een kaart gelegd op alle kaarten die al waren omgedraaid. De speler(s) moeten(en) dan drinken.", "I.  Gaat de speler in de eerste kolom de fout in, moet hij/zij één slok drinken, gaat de speler in de tweede kolom de fout in, moet hij/zij twee sloken drinken, etc..", "9.  Het spel is afgelopen als de speler(s) in de bus het veld is(/zijn) overgestoken."]}], "pullen": [1, 0.5, 1]}, {"title": "Piramide Spel", "spelers": null, "benodigdheden": ["Een spel kaarten"], "glas": "8 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  In de eerste fase van het spel worden, met de klok mee, aan elke speler vier kaarten gedeeld. Voordat hij/zij een kaart krijgt, moet de speler het volgende over de kaart zeggen, respectievelijk:", "I.  Rood of zwart: is de kaart een rode of zwarte kaart?", "II. Hoger of lager: is de kaart in waarde hoger of lager dan de eerste kaart (de Aas is hoog)?", "III. Binnen of buiten: valt de kaart tussen de eerste twee kaarten in, op het gebied van waarde, of daarbuiten?", "IV. Soort: van welke soort is de kaart, oftewel is de vierde kaart een harten, schoppen, ruiten of klaveren?", "Wanneer je een vraag fout hebt, moet je zelf één slok drinken.", "Als je een vraag goed hebt, mag je één slok uitdelen.", "2.  Wanneer iedereen vier kaarten heeft gekregen, heeft elke speler nog vijf seconden om de kaarten te memoriseren. Daarna legt iedereen zijn kaarten voor zich gesloten op tafel.", "3.  Daarna wordt met de overgebleven stapel kaarten een piramide van vier rijen/lagen van gesloten kaarten op tafel gelegd.", "4.  De kaarten van de piramide worden dan één voor één omgedraaid, beginnend bij de kaarten van de onderste rij. Als een speler meent dat een kaart, die zojuist in de piramide is omgedraaid, dezelfde waarde als één van zijn/haar kaarten heeft, mag hij/zij slokken uitdelen aan medespelers.", "I.  Voor de onderste rij van de piramide mag een speler één slok uitdelen per kaart, voor de rij daarboven mag een speler per kaart twee slokken uitdelen, etc.;", "II. Heeft de speler die kaart tweemaal voor zich liggen, dan mag hij/zij het dubbele aantal slokken uitdelen!", "Hint: Omdat jouw kaarten zijn omgedraaid, kan je ook bluffen…", "5.  De speler die de slok(ken) uitgedeeld krijgt, heeft de keuzes:", "I.  Hij/zij gelooft de speler. Hij/zij drinkt het aantal slokken;", "II. Hij/zij gelooft de speler niet. Dan moet de speler, die de slokken uitdeelt, één van zijn vier kaarten omdraaien, om te laten zien dat hij/zij wel degelijk mag uitdelen. Hier heeft de speler, die uitdeelt, één kans voor.", "i.  Ligt daar inderdaad de kaart, die recht geeft op uitdelen, dan moet de speler aan wie in eerste instantie was uitgedeeld, het dubbele aantal slokken drinken;", "Voorbeeld: Er wordt 6 omgedraaid in de tweede rij van de piramide. Speler A deelt twee slokken uit aan Speler B. Speler B gelooft Speler A niet. Speler A draait een 6 om. Nu moet Speler B vier slokken drinken (het dubbele van twee slokken).", "ii. Kan de speler, die uitdeelt, niet in één keer de juiste kaart omdraaien, dan moet de speler, die uitdeelt, zelf het uitgedeelde aantal slokken drinken.", "Voorbeeld: In dezelfde situatie als het vorige voorbeeld draait Speler A deze keer een 8 om. Nu moet Speler A zelf twee slokken nemen.", "6.  Wanneer de hele piramide is omgedraaid, moet elke speler zonder te kijken de vier kaarten voor hem/haar in volgorde opnoemen met waarde én soort. Voor elke fout (waarde en/of soort) moet de speler één slok drinken."]}, {"kop": "Variërende regel (zelf af te spreken)", "regels": ["1.  Elke keer als iemand tijdens het spel moet spieken naar zijn/haar kaarten, moet hij/zij een adtje trekken/slok drinken."]}], "pullen": [1, 0.5, 1]}, {"title": "Poefen", "spelers": null, "benodigdheden": ["Een spel kaarten"], "glas": "8 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  Eén van de spelers heeft de stapel kaarten. Deze speler zal worden ‘aangevallen’ en is dus de ‘verdediger.’", "2.  De speler links van de dealer heeft de eerste beurt (aanval) en noemt een kaart uit het kaartspel (soort + waarde). De verdediger moet drinken, wanneer:", "I.  De aanvaller de soort van de kaart goed heeft. De verdediger moet nu één slok drinken;", "Voorbeeld: Speler A verdedigt en Speler B valt aan. Speler B noemt 10. Speler A draait een 3 om. Speler A moet één slok drinken.", "II. De aanvaller de waarde van de kaart goed heeft. De verdediger moet nu twee slokken drinken.", "Voorbeeld: Speler A verdedigt en Speler B valt aan. Speler B noemt 6. Speler A draait 6 om. Speler A moet nu twee slokken drinken.", "III. De aanvaller de waarde én de soort goed heeft. De verdediger moet nu vijf slokken drinken.", "3.  Als de aanvaller zowel de waarde als de soort fout heeft, moet de aanvaller zelf één slok drinken. De beurt schuift met de klok mee naar de volgende speler.", "4.  Zo gaat de ronde door, totdat de verdediger aan de beurt is. Bij zijn/haar beurt gelden dezelfde regels, met de uitzondering dat als hij/zij iets goed heeft, iederéén dat aantal slokken moet drinken.", "5.  Als de verdediger zowel de soort als de waarde fout heeft, moet hij/zij één slok drinken. De rol van verdediger schuift dat één plaats met de klok mee door."]}, {"kop": "Speciale regel", "regels": ["1.  De ‘Poef’: Aan het begin van het spel en bij elke wissel van verdediger, mag de verdediger een Poef uitkiezen. De Poef moet dan een aantal slokken (1-5) inzetten op zwart of rood. Wanneer de kleur van de keuze van de Poef wordt getrokken, moet de verdediger het ingezette aantal slokken drinken en vice versa.", "Voorbeeld: Speler C heeft Speler D als Poef aangewezen. Speler D zet 3 slokken in op zwart. De volgende kaart die wordt gedraaid is J. De Poef moet nu 3 slokken drinken."]}], "pullen": [1, 1, 1]}, {"title": "Paardenrace", "spelers": null, "benodigdheden": ["Een spel kaarten"], "glas": "8 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  Ter voorbereiding worden alle azen uit het spel kaarten gehaald en naast elkaar, open, op tafel gelegd. Aan de zijkant van de rij met azen worden zes kaarten in een rijtje boven elkaar, gesloten, op tafel gelegd. De kaarten aan de zijkant zijn als het ware de stappen van de race. (Deze rij kan ook korter of langer. Hoe langer deze rij, hoe langer het spel duurt).", "2.  Voordat het spel begint, kan iedereen slokken inzetten op een of meerdere ‘paarden’ (één of meerdere azen). Het aantal slokken dat een persoon inzet, moet hij/zij wel eerst zelf drinken, voordat het spel kan beginnen.", "3.  Een speler neemt de stapel overgebleven kaarten, de dealer, en draait één voor één de kaarten om. Bij elke omgedraaide kaart wordt de aas van dezelfde soort één stap naar boven geschoven.", "4.  Wanneer alle azen voorbij een stap zijn, wordt de gesloten kaart, die bij de stap hoort, omgedraaid. De aas van dezelfde soort gaat een stap terug.", "5.  De winnaar is de aas die als eerste voorbij alle stappen is. De spelers, die op deze kaart hebben ingezet, mogen nu hun dubbele inzet uitdelen."]}], "pullen": [1, 1, 0]}, {"title": "Vierkanten", "spelers": "2 - 6", "benodigdheden": ["Een spel kaarten"], "glas": "8 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  Het speelveld bevat bij de start van het spel zestien kaarten die in een vierkant neer worden gelegd zodat er op elke zijde vijf kaarten liggen. Elke kaart op de hoek ligt open en de tussenliggende kaarten liggen gesloten.", "2.  De speler die aan de beurt is raadt of één gesloten kaart, welke grenzend is aan één open kaart, hoger of lager is dan de aangrenzende open kaart.", "3.  Grenst de gesloten kaart aan twee open kaarten dan raadt de speler of deze gesloten kaart binnen of buiten deze twee open kaarten valt.", "4.  Als de speler drie keer achter elkaar een gesloten kaart goed weet te raden op de manieren zoals beschreven bij punten 3 en 4 dan mag hij de beurt doorgeven aan de speler links van hem. De speler mag ook doorspelen om het moeilijker te maken voor de volgende speler", "5.  Raadt de speler de gesloten kaart fout ten opzichte van punten 3 en 4 dan drinkt hij zoveel slokken als er open kaarten aaneengesloten aan de fout geraden kaart liggen."]}], "pullen": [1]}, {"title": "Sixteen", "spelers": null, "benodigdheden": ["Een spel kaarten"], "glas": "8 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  Op de tafel liggen twee open stapels en een gesloten stapel.", "2.  Elke speler krijgt drie kaarten gedeeld. Het is de bedoeling dat de som van de twee open stapels zestien wordt. Voor de puntentelling gelden de volgende regels:", "I.  2 – 10 – aantal punten op de kaart;", "II. Boer – 11 punten;", "III. Vrouw – 12 punten;", "IV. Heer – 13 punten;", "V.  Aas – 14 punten.", "3.  Wanneer de som van de twee open stapels op zestien komt, moet de volgende speler één slok drinken.", "I.  Als de zestien wordt gevormd door tweemaal een acht, moet de vorige speler een adtje trekken!", "4.  Nadat een speler een kaart heeft opgelegd, moet hij/zij weer een kaart van de gesloten stapel pakken. De beurt schuift met de klok mee door."]}, {"kop": "Variërende regels (zelf af te spreken)", "regels": ["1.  Wanneer iemand met de kaarten die hij/zij in zijn/haar hand heeft twee keer zestien kan maken, moet de volgende speler twee slokken drinken.", "(Je mag dus meerdere kaarten per beurt opleggen, zolang de stapels maar zestien vormen).", "2.  Als je een kaart met dezelfde waarde op elkaar legt, moet de volgende speler één slok drinken.", "3.  Als een speler geen drie kaarten in zijn hand heeft, en de volgende speler heeft zijn beurt al gespeeld, dan moet de speler één slok drinken. De speler moet dan alsnog een derde kaart pakken.", "(Goede tip om de snelheid in het spel te houden)"]}], "pullen": [0, 1, 0]}, {"title": "Total Black-Out", "spelers": null, "benodigdheden": ["Een spel kaarten"], "glas": "8 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  Op tafel liggen vijf open kaarten onder elkaar. Een speler heeft de stapel gesloten kaarten en is de dealer.", "2.  De speler, die aan de beurt is, wijst een kaart/rij aan. Het maakt niet uit welke hij/zij aanwijst, de speler mag elke rij en elk uiteinde kiezen. Als de speler een kaart heeft aangewezen, zegt hij/zij of de bovenste kaart van de stapel hoger of lager is dan de aangewezen kaart.", "Let op! Als een gelijke kaart wordt getrokken, heeft de speler het fout. (Een speler kan ook kiezen voor ‘gelijk’ in plaats van hoger of lager)", "I.  Heeft de speler het goed, kan de speler doorspelen;", "II. Heeft de speler het fout, dan moet de speler drinken. Het aantal slokken wordt bepaald door het aantal kaarten van de rij waar de speler een fout heeft gemaakt.", "Voorbeeld: Speler A heeft een fout gemaakt. De rij waarin hij deze fout heeft gemaakt, had zeven kaarten. Speler A moet zeven slokken drinken.", "3.  Wanneer een speler drie keer achter elkaar het goed heeft gehad, schuift de beurt door naar de speler links van hem/haar. De dealer speelt mee."]}], "pullen": [1, 1, 1]}, {"title": "Kaartje Dobbelen", "spelers": null, "benodigdheden": ["Twee dobbelstenen", "Een spel kaarten", "Dienblad"], "glas": "8 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  Het spel begint met een gesloten stapel kaarten.", "2.  De speler, die aan de beurt is, trekt de bovenste kaart van de gesloten stapel en legt deze open op tafel. Dit is het aantal ogen dat de speler moet gooien. De telling is als volgt:", "I.  2 – 10 – aantal punten op de kaart;", "II. Boer – 11 punten;", "III. Vrouw – 12 punten;", "IV. Heer – vier slokken uitdelen;", "V.  Aas – iedereen vier slokken drinken;", "3.  De speler heeft drie worpen om het juiste totaal aantal ogen te gooien. Je mag geen dobbelstenen laten liggen.", "N.B. Om de slagingskans te vergroten, kan je afspreken dat je een dobbelsteen één keer mag laten liggen.", "I.  Heeft de speler niet het juiste aantal ogen gegooid, dan moet hij/zij het verschil in aantal ogen in slokken drinken;", "Voorbeeld: Speler A trekt Q. Aan het einde van haar beurt ligt er [4][5]. Zij had 11 ogen moeten gooien, maar heeft er slechts 9. Zij moet nu twee slokken drinken.", "II. Heeft de speler wel het juiste aantal ogen gegooid, dan mag hij/zij een half adtje uitdelen.", "4.  De speler links van hem/haar is nu aan de beurt."]}], "pullen": [1, 1, 0]}, {"title": "Chinees Roulette", "spelers": null, "benodigdheden": ["Eén dobbelsteen", "Zes shotglaasjes"], "glas": "Niet van toepassing", "secties": [{"kop": "Spelregels", "regels": ["1.  De zes shotglaasjes staan op een rij. De shotglaasjes staan voor het aantal ogen: 1 tot en met 6. Het tweede shotglaasje (‘2’) is altijd gevuld.", "2.  De speler die aan de beurt is, gooit de dobbelsteen:", "I.  Is het shotglaasje, dat voor het aantal gegooide ogen staat, leeg? Dan moet de speler dit glaasje bijvullen en is zijn/haar beurt afgelopen. De beurt gaat door met de klok mee;", "II. Is het shotglaasje, dat voor het aantal gegooide ogen staat, vol? Drinkt hij/zij dit shotglaasje en werpt opnieuw. Wanneer dit shotglaasje ‘2’ betreft, wordt deze meteen weer bijgevuld.", "3.  Als een speler het laatste lege shotglaasje moet vullen, heeft hij/zij ‘roulette’ gegooid en moet hij/zij alle shotglaasjes leegdrinken. Hij/zij blijft dan aan de beurt.", "4.  Als alle shotglaasjes, behalve ‘2’, leeg zijn en de speler, die aan de beurt is, gooit [2], dan moet die speler eerst shotglaasje ‘2’ leegdrinken en daarna nog eens allemaal. De beurt is nog niet voorbij."]}], "pullen": [1, 0, 0.5]}, {"title": "Oude Bami, Nieuwe Bami", "spelers": "2 (eventueel 3)", "benodigdheden": ["Eén dobbelsteen"], "glas": "8 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  Voor de start van het spel wordt bepaald wie de oude bami en wie de nieuwe bami is.", "2.  De spelers gooien om de beurt één keer met de dobbelsteen.", "3.  De speler die oude bami heeft gekozen drinkt één slok wanneer het getal 1, 2 of 3 gegooid wordt.", "4.  De speler die nieuwe bami heeft gekozen drinkt één slok wanneer het getal 4, 5 of 6 gegooid wordt.", "5.  Eventueel kan er een derde speler meedoen. In dat geval wordt er ook een midden bami gekozen. De midden bami drinkt één slok wanneer het getal 3 of 4 gegooid wordt.", "6.  De regels van het spel mogen niet worden uitgelegd."]}], "pullen": [1, 0, 1]}, {"title": "Vieren", "spelers": "2 - ∞", "benodigdheden": ["Eén dobbelsteen"], "glas": "8 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  De speler die aan de beurt is pakt de dobbelsteen in de hand en roept vier alvorens de dobbelsteen te gooien.", "2.  Als de speler, die aan de beurt is, geen vier roept voordat hij gooit dan neemt hij zelf een halve bak en gooit hij overnieuw.", "3.  Als de speler, die aan de beurt is, vier geroepen heeft en vier [4] gooit dan trekt die speler zelf een volledige bak om de winst te vieren.", "4.  Als de speler, die aan de beurt is, vier geroepen heeft en geen vier [4] gooit dan neemt hij zelf een slok om het verdriet weg te drinken.", "5.  Na elke ronde wordt de dobbelsteen met de klok mee doorgegeven."]}], "pullen": [1, 0, 1]}, {"title": "Eigen Risico", "spelers": null, "benodigdheden": ["Eén dobbelsteen", "Halve liter pul"], "glas": "Niet van toepassing", "secties": [{"kop": "Spelregels", "regels": ["1.  De speler, die aan de beurt is, gooit bier in de halve liter pul die op tafel staat:", "I.  De speler kan maximaal zijn glas in de pul leeggooien. Je mag maar één keer de pul bijschenken, het glas bijvullen mag dus niet;", "II. Als de pul al vol is, kan deze natuurlijk niet worden bijgevuld.", "2.  Hij/zij noemt hierna een getal tussen de 1 en de 6.", "3.  De speler gooit de dobbelsteen:", "I.  Gooit de speler een ander aantal ogen dan hij/zij heeft gezegd, dan schuift de beurt door naar de speler links van hem/haar;", "II. Gooit de speler het aantal ogen dat hij/zij heeft gezegd, moet hij/zij zelf de pul leegdrinken.", "4.  De verliezende speler vult opnieuw de halve liter pul naar eigen wens en is opnieuw aan de beurt."]}, {"kop": "Variërende regel (zelf af te spreken)", "regels": ["1.  Als je aan de beurt bent, moet je altijd je glas helemaal in de pul leeggooien."]}], "pullen": [1, 1, 1]}, {"title": "Drommels", "spelers": "2", "benodigdheden": ["Twee dobbelstenen"], "glas": "8 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  Beide spelers nemen één dobbelsteen in de hand en gooien tegelijkertijd de dobbelsteen.", "2.  De speler die het laagst gegooid heeft roept ‘drommels’ en neemt een slok van zijn glas.", "3.  Worden er evenveel ogen gegooid in een beurt dan kan het totaal aantal ogen uitgedeeld worden aan een andere persoon die niet deelneemt aan het spel en die zich in dezelfde ruimte bevindt. Hij/zij dient het aantal slokken te nemen dat wordt bepaald door het aantal gegooide ogen."]}], "pullen": [1, 0, 1]}, {"title": "7, 8, 9", "spelers": null, "benodigdheden": ["Twee dobbelstenen", "Drie extra glazen, bij voorkeur buikjes", "Dienblad"], "glas": "Niet van toepassing", "secties": [{"kop": "Spelregels", "regels": ["1.  De drie buikjes staan voor de getallen 7, 8, en 9. Het meest linkse glas is te allen tijde minimaal halfvol.", "2.  Als een speler aan de beurt is, gooit hij/zij beide dobbelstenen:", "I.  Gooit hij/zij zeven, acht of negen ogen in totaal, zal hij/zij nog een keer moeten gooien. Maar eerst moet hij/zij:", "i.  in het geval van zeven ogen in totaal, zoveel glazen als hij/zij wil bijvullen met zoveel bier als hij/zij wil;", "ii. in het geval van acht ogen in totaal, de helft van al het bier in de drie glazen opdrinken;", "iii. in het geval van negen ogen in totaal, al het bier in de drie glazen opdrinken.", "II. Gooit de speler geen zeven, acht of negen ogen in totaal, is zijn/haar beurt afgelopen en schuift de beurt met de klok mee door naar de volgende speler."]}], "pullen": [1, 1, 1]}, {"title": "Blind Mexxen", "spelers": null, "benodigdheden": ["Twee dobbelstenen", "Ondoorzichtige beker"], "glas": "8 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  De speler, die opzet, gooit beide dobbelstenen onder de beker.", "2.  De speler, die opzet, kijkt wat er onder de beker ligt en geeft een Mexx combinatie (zie blz. 32) door aan de volgende speler of gooit opnieuw en geeft ‘blind’ een Mexx combinatie door.", "Hint: Omdat de andere spelers niet weten wat er ligt, hoef je niet de waarheid te vertellen…", "3.  De speler links van de speler, die op heeft gezet, heeft de volgende keuzes:", "I.  De speler kijkt niet onder de beker en geeft door;", "II. De speler kijkt niet onder de beker en gooit beide dobbelstenen opnieuw onder de beker. Hierna mag de speler onder de beker kijken. De speler kan dan beslissen om nog een keer te gooien of door te geven. Als hij/zij nogmaals gooit, mag hij/zij niet onder de beker kijken voordat hij/zij de beker doorgeeft;", "III. De speler kijkt onder de beker. Op dit moment moet deze speler op zijn minst één dobbelsteen opnieuw gooien. Nadat een speler heeft gegooid mag hij/zij nogmaals kijken wat er onder de beker ligt, alvorens hij de beker doorgeeft. De speler kan daarna ook beslissen om nog een keer te gooien, maar dan mag hij/zij niet meer kijken wat er onder de beker ligt, voordat hij/zij hem doorgeeft;", "4.  De speler geeft de beker door aan de volgende speler.", "Let op! Je moet altijd een hogere Mexx combinatie doorgeven dan je doorgegeven hebt gekregen! (Voor scores, zie blz. 32)", "5.  Zo gaat de ronde door, totdat:", "I.  Een speler de voorganger niet gelooft en de beker trekt:", "i.  Ligt er iets lagers dan wat de voorganger zegt, moet de voorganger drinken;", "ii. Ligt er precies wat de voorganger zegt, dan moet de speler drinken;", "iii. Ligt er iets hogers dan wat de voorganger zegt, dan moet de speler drinken.", "II. Een speler beweert Mexx gegooid te hebben. De volgende speler moet dan zeggen of hij dit gelooft of niet en trekt vervolgens de beker:", "i.  Gelooft hij/zij de voorganger en ligt er Mexx, dan heeft hij/zij driemaal om ook Mexx te gooien. Lukt dit niet, moet speler drinken. Lukt dit wel, begint een nieuwe ronde;", "ii. Gelooft hij/zij de voorganger en ligt er geen Mexx, dan moet de speler drinken;", "iii. Gelooft hij/zij de voorganger niet en ligt er Mexx, dan moet de speler drinken;", "iv. Gelooft hij/zij de voorganger niet en ligt er geen Mexx, dan moet de voorganger drinken."]}, {"kop": "Variërende regels (zelf af te spreken)", "regels": ["1.  Als je [1][3] gooit mag je een slok uitdelen (jij bent de ‘uitdeler’) aan een andere speler. Deze speler heeft de keuze:", "I.  Gelooft de speler de worp, moet hij/zij een slok drinken;", "II. Gelooft de speler de worp niet, maar ligt er wel [1][3], dan moet hij/zij twee slokken drinken;", "III. Gelooft de speler de worp niet, en ligt er geen [1][3], dan moet de uitdeler een slok drinken.", "De beurt van de uitdeler begint daarna opnieuw.", "1.  Gelooft een speler de voorganger niet, maar ligt er precies wat de voorganger heeft gezegd, dan moet hij/zij dubbel drinken."]}], "pullen": [0, 1, 0]}, {"title": "Driemannen", "spelers": null, "benodigdheden": ["Twee dobbelstenen", "Dienblad"], "glas": "8 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  Elke speler gooit éénmaal beide dobbelstenen. Je mag nooit een dobbelsteen laten liggen. De beurt gaat met de klok mee. Het spel begint zonder Drieman.", "2.  Wanneer iemand [1][2] gooit, is deze speler de ‘Drieman.’ Bij elke [3], die wordt gegooid, moet de Drieman één slok drinken.", "3.  In de volgende gevallen mag er worden uitgedeeld, of moet er gedronken worden:", "I.  Gooi je 7, 9 en 11 ogen:", "i.  Bij een totaal aantal ogen van 7, moet de speler voor jou één slok nemen;", "ii. Bij een totaal aantal ogen van 9, moet je zelf één slok nemen;", "iii. Bij een totaal aantal ogen van 11, moet de speler na jou één slok nemen.", "II. Bij dubbelgooien:", "i.  Bij dubbel [1], [2],[4], [5], [6] mag je het aantal ogen, dat je hebt gegooid, uitdelen. Je mag dit over meerdere spelers verdelen;", "Voorbeeld: Speler A gooit [5][5]. Hij mag nu tien slokken uitdelen.", "ii. Uitzondering hierop is [3][3]. Als er een Drieman is, mag de Drieman tien slokken uitdelen. Is er geen Drieman, dan mag de speler, die dit heeft gegooid, zes slokken uitdelen."]}, {"kop": "Kenmerk van Drieman", "regels": ["Wanneer de Drieman wisselt, wordt er normaal gesproken het volgende gezongen:", "[Muzieknoot I] Nieu-we Drie-man! Ja-la la-la-la la-la. (2x) [Muzieknoot I]", "Of", "[Muzieknoot I]Nieuwe nieuwe NIEU-WE Drie-man! Ja-la-la la-la-la la-la [Muzieknoot I]"]}, {"kop": "Variërende regels (zelf af te spreken)", "regels": ["1.  Wanneer de Drieman zelf weer [1][2] gooit, is hij/zij de dubbele Drieman. Bij elke [3] die wordt gegooid, moet hij/zij nu twee slokken drinken. Bij elke [3][3] mag hij/zij nu twintig slokken uitdelen, etc..", "2.  Het aantal ogen dat wordt gebruikt bij regel 3.I. kan worden vervangen door 7, 8 en 9, respectievelijk.", "3.  Elke speler heef een waarde van 2 tot en met 12. Wanneer het aantal ogen van ‘jouw’ waarde wordt gegooid, moet jij één slok nemen."]}], "pullen": [1, 1, 0]}, {"title": "Jackpot", "spelers": null, "benodigdheden": ["Twee dobbelstenen", "Jackpot-spel of viltjes genummerd 1 t/m 9", "Dienblad"], "glas": "8 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  De speler gooit beide dobbelstenen in één worp.", "2.  Afhankelijk van wat er is gegooid, mag de speler één cijfer omdraaien. Je hebt de keuze tussen:", "I.  Het aantal ogen van één van de dobbelstenen om te draaien;", "II. De soms van het aantal ogen van beide dobbelstenen om te draaien.", "3.  Zo blijf je aan de beurt totdat:", "I.  Je geen cijfer meer kan omdraaien. Je moet dan zoveel slokken drinken als cijfers, die je nog niet om hebt kunnen draaien;", "Voorbeeld: Speler A heeft nog 3, 4, 7 en 9 open liggen en gooit [6][2]. Speler A kan niets meer omdraaien en omdat hij nog vier cijfers heeft open liggen, moet hij vier slokken drinken.", "II. Alle cijfers zijn omgedraaid zijn (‘Jackpot’). Dan moeten alle overige spelers een adtje trekken.", "4.  De beurt gaat door met de klok mee en de volgende speler mag Jackpot proberen te gooien."]}], "pullen": [1, 1, 0]}, {"title": "Mexxpot", "spelers": null, "benodigdheden": ["Twee dobbelstenen", "Jackpot-spel of viltjes genummerd 1 t/m 9", "Dienblad", "Dit spel is een combinatie van Mexxen en Jackpot."], "glas": "8 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  De speler gooit beide dobbelstenen in één worp.", "I.  Bij elke worp gelden de regels van Mexx:", "i.  [1][3] is uitdelen en telt niet mee als worp;", "ii. De laagste score is vast;", "iii. Etc.", "II. Bij elke worp gelden de regels van Jackpot:", "i.  Na elke worp moet je een cijfer omdraaien.", "2.  Na drie keer werpen, schuift de beurt met de klok mee.", "3.  Als een speler niets meer kan omdraaien, moet hij/zij het aantal resterende cijfers in slokken drinken. Als hij/zij alle cijfers heeft om kunnen draaien, moet de rest een adtje trekken.", "Let op! De Mexx ronde gaat gewoon nog door!", "4.  Als de Mexx ronde is afgelopen, moet de speler met de laagste score drinken. Hij/zij mag ook weer opzetten.", "Let op! De Jackpot ronde gaat gewoon nog door, de Jackpot ronde wordt dus niet opnieuw gestart."]}], "pullen": [1, 0.5, 1]}, {"title": "Mexx", "spelers": null, "benodigdheden": ["Twee dobbelstenen", "Dienblad"], "glas": "8 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  Iedere speler mag in principe driemaal gooien. De beurt gaat met de klok mee.", "2.  Wanneer een [1] of een [2] wordt gegooid, mag je deze éénmaal laten liggen.", "3.  Na drie worpen is je score bekend.", "De puntentelling verloopt als volgt:", "I.  De hoogste ogen zijn de tientallen, de laagste zijn de eenheden.", "Voorbeeld: Speler A gooit [6][3], hij heeft een score van 63 gegooid.", "II. Als je dubbel gooit, heb je in de honderdtallen gescoord.", "Voorbeeld: Speler B gooit [4][4], zij heeft een score van 400 gegooid.", "III. Het hoogste is Mexx, je beurt is dan meteen afgelopen.", "Voorbeeld: Speler C gooit [1][2], zij heeft Mexx gegooid.", "4.  De speler met de laagste score heeft verloren en moet drinken.", "I.  Is er geen Mexx gegooid, dan moet de verliezer één slok drinken;", "II. Per Mexx, die is gegooid, moet de verliezer twee slokken, drie slokken of een half adtje drinken, afhankelijk van wat afgesproken is.", "5.  Hebben meerdere speler de laagste score gegooid, komt er nog een extra ronde om de verliezer aan te duiden. Er zijn twee mogelijkheden:", "I.  Mexx – elke speler mag éénmaal gooien. De speler met de laagste (Mexx)score verliest;", "II. Ogen – elke speler mag éénmaal gooien. De speler, die het minst aantal ogen gooit, verliest.", "Voorbeeld: Speler D heeft een score van 52, Speler E een score van 200, Speler F een score van 52. Speler D en Speler F zijn beide laag en moeten nog een ronde spelen. Speler D kiest Mexx. Hierin scoort Speler D 63 en Speler F 61. Speler F verliest."]}, {"kop": "Bijzondere regels", "regels": ["1.  [1][3] telt niet mee als worp, maar je mag één slok uitdelen.", "2.  De laagste score staat ‘vast.’ Wanneer jij hetzelfde gooit als de speler, die tot dan toe de laagste score heeft, is jouw beurt voorbij. Jij bent samen met die speler laag.", "3.  ‘Adtje op de kruk.’ Wanneer een speler voor de derde maal achtereen dezelfde score gooit, moet hij/zij een adtje op een kruk doen. Deze telling wordt doorgegeven tussen spelers.", "4.  Wanneer de speler, die de ronde begint (=opzet), in minder dan drie worpen [1][2] gooit, mag de rest van de spelers slechts het aantal keren gooien dat de speler, die opzette, nodig had om [1][2] te gooien.", "Voorbeeld: Speler G zet op met [1][2] in slechts tweemaal gooien. De rest van de spelers mogen dan ook tweemaal gooien."]}, {"kop": "Variërende regels (zelf af te spreken)", "regels": ["1.  [3][2] is altijd vast, ook al heeft nog niemand dat gegooid.", "2.  Bij [1][2] of [1][3] mag je niets laten liggen.", "3.  Als je dubbel gooit, moet je zelf één slok nemen."]}], "pullen": [1, 1, 0]}, {"title": "PowerMexx", "spelers": null, "benodigdheden": ["twee dobbelstenen", "dienblad"], "glas": "8 slokken", "secties": [{"kop": "Bijzonderheden", "regels": ["Altijd maar éénmaal gooien.", "Nooit iets laten liggen.", "[3][3] is PowerMexx. Staat gelijk aan twee Mexx."]}], "variant": "Mexx", "pullen": [0.5, 1, 1]}, {"title": "Inverse Mexx", "spelers": null, "benodigdheden": ["twee dobbelstenen", "dienblad"], "glas": "8 slokken", "secties": [{"kop": "Bijzonderheden", "regels": ["De puntentelling is andersom, bijvoorbeeld:", "[6][3] = 36;", "[4][4] = 44.", "[1][2] blijft Mexx, maar is dan de laagste score.", "De speler met de hoogste score verliest."]}], "variant": "Mexx", "pullen": [1, 1, 0]}, {"title": "Nostradamus PowerMexx", "spelers": null, "benodigdheden": ["twee dobbelstenen", "dienblad"], "glas": "8 slokken", "secties": [{"kop": "Bijzonderheden", "regels": ["Voordat een speler gooit, wijst hij/zij twee spelers aan. Elk van deze spelers voorspelt het aantal ogen van één dobbelsteen.", "De speler gooit de dobbelstenen:", "Als één voorspeller gelijk heeft, mag hij/zij een half adtje uitdelen;", "Als een voorspeller geen gelijk heeft, moet hij/zij het verschil in aantal ogen in slokken drinken;", "Als beide voorspeller gelijk hebben, moeten beide voorspellers een adtje trekken.", "N.B. Bij onduidelijkheden over wie juist heeft voorspeld en/of over het aantal slokken dat gedronken moet worden, heeft de oudste speler altijd de meest gunstige positie."]}], "variant": "Mexx", "pullen": [0.5, 1, 1]}, {"title": "Ottomaans Mexx", "spelers": null, "benodigdheden": ["één dobbelsteen per speler"], "glas": "8 slokken", "secties": [{"kop": "Bijzonderheden", "regels": ["De oudste speler werpt alle dobbelstenen;", "Van alle geworpen dobbelstenen, legt hij/zij één dobbelsteen naar keuze apart. Dit is zijn/haar dobbelsteen.", "Zo wordt de ronde op leeftijd afgemaakt.", "Wie aan het einde van de ronde de dobbelsteen met het laagste aantal ogen heeft gekozen, heeft verloren en moet drinken. Bij gelijkspel drinken meerdere spelers."]}, {"kop": "Variërende regels (zelf af te spreken)", "regels": ["Aan het begin kiezen alle spelers een getal, dat op de dobbelsteen staat, uit. De oudste speler mag als eerste kiezen. Alle spelers hebben een ander getal. Wanneer een dobbelsteen wordt weggelegd, moet de speler, die dat getal heeft gekozen, één slok drinken.", "Wanneer jij een dobbelsteen weglegt en andere spelers leggen een dobbelsteen met hetzelfde aantal ogen ook weg, moet jij één slok nemen.", "Wanneer jij een dobbelsteen weglegt en andere spelers gooien een dobbelsteen met hetzelfde aantal ogen, moet je voor elk zo’n dobbelsteen één slok nemen."]}], "variant": "Mexx", "pullen": [1, 0, 0]}, {"title": "Snelmexx", "spelers": null, "benodigdheden": ["Bij vier tot zes spelers, twee paar dobbelstenen", "Bij zeven of acht spelers, drie paar dobbelstenen", "etc."], "glas": "8 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  Bij Snelmexx gelden dezelfde regels als bij normaal Mexx.", "2.  Bij het begin worden de paren dobbelstenen aan spelers gegeven, waarbij er ongeveer evenveel spelers tussen de verschillende paren dobbelstenen zitten.", "Voorbeeld: Bij een spel met zeven spelers, Spelers A, B, C, D, E, F en G, zittend op volgorde, worden bij het begin de dobbelstenen gegeven aan Speler A, Speler C en Speler E (of Speler F).", "3.  Als je de dobbelstenen hebt, moet je zo snel mogelijk [1][2] gooien. Pas als je Mexx hebt gegooid, mag je de dobbelstenen met de klok mee doorgeven. Het kan dus zo zijn dat je vaker dan driemaal gooit.", "4.  Wanneer een speler [1][3] gooit, moet hij/zij ‘Eénendertig’ roepen. Elke speler, die een paar dobbelstenen heeft, moet dan eerst één slok nemen, voordat hij/zij door mag gooien.", "5.  Als je bent ingehaald, moet je eerst een half adtje trekken, voordat je door mag gooien.", "Let op! Het spel gaat dan gewoon door."]}, {"kop": "Variërende regel (zelf af te spreken)", "regels": ["1.  Als iemand is ingehaald, stopt het spel wel. De verliezer moet een (half) adtje trekken. Daarna worden de dobbelstenen weer even verdeeld over de spelers."]}], "pullen": [1, 1, 0]}, {"title": "1’tje Gooien", "spelers": null, "benodigdheden": ["Drie dobbelstenen", "Dienblad"], "glas": "8 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  [6]Met twee van de drie dobbelstenen werp je steeds. Iedere speler gooit per beurt eenmaal beide dobbelstenen. De beurt gaat met de klok mee.", "2.  Aan het begin ligt de derde dobbelsteen op de .", "3.  De derde dobbelsteen mag worden gedraaid naar het volgende getal (je telt af van [6] naar [1]), wanneer:", "I.  Een speler een [1] gooit. Je draait dan de dobbelsteen naar het volgende getal;", "II. Een speler dubbel gooit. Je draait dan de dobbelsteen naar het volgende getal;", "III. Een speler [1][1] gooit. Je draait dan de dobbelsteen twee keer naar het volgende getal;", "IV. [6]Een speler [1][2] gooit. Je draait dan de dobbelsteen drie keer naar het volgende getal.", "4.  Het spel is afgelopen als de dobbelsteen weer terug op de ligt, de speler die hem op de [6] heeft moeten draaien, heeft verloren en moet een slok/half adtje drinken."]}, {"kop": "Variërende regel (zelf af te spreken)", "regels": ["1.  Bij dubbel gooien of per keer draaien, moet je één slok drinken."]}], "pullen": [0.5, 1, 0]}, {"title": "Tegendraads", "spelers": null, "benodigdheden": ["Drie dobbelstenen", "Dienblad"], "glas": "8 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  Een beurt begint met het gooien van één dobbelsteen.", "2.  Nadat deze dobbelsteen is gegooid, moet de speler voorspellen hoeveel ogen hij/zij met drie dobbelstenen gaat gooien.", "3.  De speler gooit de overige twee dobbelstenen:", "I.  De speler heeft het aantal ogen goed geraden. In dit geval mag hij/zij het aantal ogen in slokken uitdelen;", "II. De speler heeft minder ogen gegooid dan hij/zij heeft voorspeld. In dit geval moet de speler het verschil in aantal ogen in slokken drinken;", "Voorbeeld: Speler A gooit met zijn eerste dobbelsteen een [4]. Hierop voorspelt Speler A dat hij 12 ogen gaat gooien. Aan het einde van zijn beurt ligt het volgende op tafel: [5][4][1]. Speler A moet (12 - 10 =) twee slokken drinken.", "III. De speler heeft meer ogen gegooid dan hij/zij heeft voorspeld. In dit geval moet de speler het dubbele verschil in aantal ogen in slokken drinken. (De speler heeft te laag ingezet en wordt daarvoor ‘gestraft’).", "Voorbeeld: Speler B gooit met haar eerste dobbelsteen een [2]. Hierop voorspelt Speler B dat zij 8 ogen gaat gooien. Aan het einde van haar beurt ligt het volgende op tafel: [6][3][2]. Dit zijn 11 ogen, dus moet Speler B (2 x 3 = ) zes slokken drinken.", "4.  De beurt is voorbij en gaat met de klok mee verder."]}, {"kop": "Bijzondere regels", "regels": ["1.  Wanneer een speler na de eerste worp voorspelt dat hij/zij drie dezelfde dobbelstenen gaat gooien en dit bovendien ook gooit, mag hij/zij het dubbele aantal slokken uitdelen.", "Voorbeeld: Speler C gooit met zijn eerste dobbelsteen een [3]. Hij voorspelt dat hij negen ogen gaat gooien en gooit dit ook. Speler C mag nu (2 x 9 =) 18 slokken uitdelen.", "2.  Verzekering: een speler kan ervoor kiezen de laatste twee dobbelstenen één voor één te gooien. Na de tweede dobbelsteen te hebben gegooid, kan hij/zij een ‘verzekering kopen’:", "I.  Om dit te doen moet hij/zij eerst een half adtje trekken;", "II. Wanneer de speler één oog meer of minder heeft gegooid dat hij/zij eerst had voorspeld, mag hij/zij alsnog slokken uitdelen. Het aantal gegooide ogen wordt uitgedeeld;", "Voorbeeld: Speler C heeft 13 ogen voorspeld en een verzekering gekocht. Aan het einde van de beurt ligt het volgende op tafel: [6][4][2]. Dit zijn 12 ogen, dat valt binnen de verzekering. Speler C mag nu 12 slokken uitdelen.", "III. Gooit de speler buiten deze marge, moet hij/zij het dubbele aantal slokken drinken van wat gebruikelijk is.", "Voorbeeld: Speler D heeft 10 ogen voorspeld en een verzekering gekocht. Aan het einde van de beurt ligt het volgende op tafel: [3][3][1]. Dit zijn 7 ogen, dat valt buiten de verzekering. Speler D moet nu zes slokken drinken (het dubbele van 3)."]}, {"kop": "Variërende regel (zelf af te spreken)", "regels": ["1.  Het aantal slokken dat wordt uitgedeeld/gedronken, wordt gehalveerd. Halve slokken worden naar boven afgerond."]}], "pullen": [0.5, 1, 1]}, {"title": "Straatje Leggen", "spelers": null, "benodigdheden": ["Vier dobbelstenen", "Dienblad"], "glas": "8 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  De speler, die aan de beurt is, gooit alle vier de dobbelstenen.", "2.  De speler noemt dan op welke straat hij/zij wilt halen, dit mag gedurende de beurt nog worden veranderd.", "Voorbeeld: Speler A gooit in de eerste worp [6][6][4][2]. Speler A geeft aan voor de straat [3] tot en met [6] te gaan.", "3.  Na drie worpen heeft de speler:", "I.  De straat gehaald. Dan mag de speler het hoogst aantal ogen van de straat in slokken uitdelen. De slokken mogen over meerdere spelers worden verdeeld;", "Voorbeeld: Speler B heeft na drie worpen het volgende gegooid: [5][4][3][2] .Speler B mag nu vijf slokken uitdelen.", "II. De straat niet gehaald. Dan moet de speler de helft van het aantal ogen van de ontbrekende dobbelstenen drinken. Bij oneven aantallen wordt er naar boven afgerond.", "Voorbeeld: Speler C gaat voor de straat [3] tot en met [6]. Na drie worpen heeft Speler C het volgende gegooid:", "[6][4][3][1]. Speler C mist een vijf en moet (5 : 2 =) 2,5 slokken drinken. 2,5 wordt afgerond naar 3 slokken.", "4.  De beurt is voorbij en schuift met de klok mee door."]}], "pullen": [1, 1, 0]}, {"title": "Adtzee", "spelers": null, "benodigdheden": ["Vijf dobbelstenen", "Dienblad", "Pen en papier"], "glas": null, "secties": [{"kop": "Voorbereiding", "regels": ["1.  Eén van de spelers maakt het speelveld voor Adtzee. Dit bestaat uit een kolom met alle combinaties en een eigen kolom voor elke speler. In dit speelveld wordt elke combinatie, die wordt geprobeerd te halen, afgestreept."]}, {"kop": "Spelregels", "regels": ["1.  Wanneer een speler aan de beurt is, gooit deze alle vijf de dobbelstenen.", "2.  Na zijn/haar eerste worp kiest de speler welke combinatie hij/zij wil proberen te halen in zijn/haar beurt. De speler kan kiezen uit de volgende combinaties:", "I.  Drie maal [1];", "II. Drie maal [2];", "III. Drie maal [3];", "IV. Drie maal [4];", "V.  Drie maal [5];", "VI. Drie maal [6];", "I – VI = ‘De Bovenste Helft’", "VII. Three of a Kind – drie dezelfde stenen naar keuze;", "VIII. Four of a Kind – vier dezelfde stenen naar keuze;", "IX. Full House – drie dezelfde stenen naar keuze en twee dezelfde stenen naar keuze;", "X.  Kleine Straat – vier opeenvolgende stenen;", "XI. Grote Straat – vijf opeenvolgende stenen;", "XII. Adtzee – vijf dezelfde stenen naar keuze.", "XIII.", "Bij combinaties VII – XII moet je nauwkeurig aangeven waar je voor wilt gaan.", "Voorbeeld: Speler A wilt gaan voor een kleine straat. Hij moet nu zeggen van waar tot waar deze straat loopt. Dus: kleine straat van [2] tot en met [5].", "3.  Per beurt heb je maximaal drie worpen om je combinatie te halen. Daarna draait de beurt met de klok mee door.", "I.  Haal je je combinatie niet, dan moet je slokken drinken. Het aantal slokken, dat je moet drinken, wordt bepaald door het aantal ogen dat je mist voor je combinatie;", "Voorbeeld: Speler B gaat voor Full House met driemaal [4] en tweemaal [1]. Na drie worpen heeft Speler B het volgende gegooid: [4][4][1][1][5]. Speler B moet nu vier slokken drinken, hij mist immers een [4].", "II. Haal je je combinatie wel, dan mag je slokken uitdelen naar het schema op de volgende pagina.", "4.  Elke combinatie mag je maar één keer proberen, ook al heb je de combinatie in je eerste poging niet gehaald.", "5.  Na je eerste worp kan je alleen nog je combinatie veranderen door een adtje te trekken."]}, {"kop": "Variërende regels (zelf af te spreken)", "regels": ["1.  Wanneer je niet alle drie de worpen nodig hebt om een combinatie te halen, dan mag je het dubbele aantal slokken uitdelen.", "2.  Als je de laatste speler bent die een bepaalde combinatie nog moet proberen te halen, dan worden alle slokken verdubbeld (zowel voor het uitdelen als voor het zelf drinken).", "3.  Als in de laatste ronde van het spel elke speler enkel nog Adtzee open heeft staan, dan worden alle slokken verdubbeld.", "+------------------+-------------------------------------------------+---------------+--------------------+", "| Combinatie       | Uitdeelregel                                    | Voorbeeld     | Uitdelen           |", "+==================+=================================================+===============+====================+", "| ‘Bovenste Helft’ | Bij drie dobbelstenen zit je goed.              | [5][5][5][5]  | 5 slokken          |", "|                  |                                                 |               |                    |", "|                  | Elke extra steen mag je uitdelen.               | [3]           | (één [5] ‘extra’)  |", "+------------------+-------------------------------------------------+---------------+--------------------+", "| Three of a Kind  | De som van de twee ‘reststenen.’                | [3][3][3]     | 8 slokken          |", "|                  |                                                 |               |                    |", "|                  |                                                 | [6][2]        | (6 + 2)            |", "+------------------+-------------------------------------------------+---------------+--------------------+", "| Four of a Kind   | Het dubbele van de ‘reststeen.’                 | [4][4][4][4]  | 10 slokken         |", "|                  |                                                 |               |                    |", "|                  |                                                 | [5]           | (5 x 2)            |", "+------------------+-------------------------------------------------+---------------+--------------------+", "| Full House       | De som van de componenten van de Full House.    | [1][1][1]     | 7 slokken          |", "|                  |                                                 |               |                    |", "|                  |                                                 | [6][6]        | (1 + 6)            |", "+------------------+-------------------------------------------------+---------------+--------------------+", "| Kleine Staat     | Hoogste steen van de straat.                    | [6][5][4][3]  | 6 slokken          |", "|                  |                                                 |               |                    |", "|                  |                                                 | [5]           | (6)                |", "+------------------+-------------------------------------------------+---------------+--------------------+", "| Grote Straat     | Het dubbele van de hoogste steen van de straat. | [5][4][3]     | 10 slokken         |", "|                  |                                                 |               |                    |", "|                  |                                                 | [2][1]        | (5 x 2)            |", "+------------------+-------------------------------------------------+---------------+--------------------+", "| Adtzee           | Iedereen één adtje.                             | [2][2][2]     | Iedereen één adtje |", "|                  |                                                 |               |                    |", "|                  |                                                 | [2][2]        |                    |", "+------------------+-------------------------------------------------+---------------+--------------------+"]}], "pullen": [1, 1, 1]}, {"title": "Nixxen", "spelers": null, "benodigdheden": ["Vijf dobbelstenen", "Dienblad"], "glas": "8 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  De ronde begint met een speler die alle dobbelstenen gooit.", "2.  Per worp mag, en moet, de speler slechts één dobbelsteen laten liggen, met uitzondering van de drie, daarvan mag je zoveel laten liggen als je wilt.", "3.  Wanneer alle dobbelstenen zijn weggelegd, worden de punten geteld. De puntentelling gaat als volgt:", "I.  De stenen [1], [2], [4], [5], en[6] hebben de waarden van hun aantal ogen;", "II. De [3] heeft de waarde 0.", "Voorbeeld: Speler A heeft het volgende gegooid: [1], [2], [2], [3], [5]. Speler A heeft deze beurt 10 punten.", "4.  De beurt gaat met de klok mee.", "5.  Als alle spelers zijn geweest, worden de punten van elke speler naast elkaar gelegd. De speler met het hoogste aantal punten moet het aantal ogen van de speler met het laagste aantal punten in slokken drinken.", "Voorbeeld: In een ronde van vier spelers heeft Speler A 10 punten, Speler B heeft 12 punten, Speler C heeft 7 punten en Speler D heeft 11 punten. Speler B heeft de meeste punten en moet zeven slokken drinken (de score van Speler C, als speler met de laagste score)."]}, {"kop": "Bijzondere regels", "regels": ["1.  Wanneer twee of meer spelers hetzelfde aantal punten hebben als hoogste score spelen zij een ‘double or nothing’ ronde. De regels zijn hetzelfde, maar deze keer drinkt de verliezende speler tweemaal het aantal ogen, dat de speler met het laagste aantal punten heeft gegooid, in slokken", "Voorbeeld: In de ronde van het vorige voorbeeld heeft Speler E ook 12 punten gegooid. Speler B en Speler E spelen de double or nothing ronde. Speler B heeft 6 punten en Speler E heeft 5 punten. Speler B moet nu 10 slokken drinken (2 x 5 slokken van Speler E).", "2.  Wanneer een speler alle dobbelstenen met een gelijk aantal ogen weg heeft gelegd, is de ronde afgelopen en moet elke andere speler een adtje trekken."]}], "pullen": [1, 0.5, 1]}, {"title": "Streepjesspel", "spelers": null, "benodigdheden": ["Zes dobbelstenen", "Dienblad", "Pen en papier"], "glas": "15 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  Aan het begin van de beurt gooit de speler alle dobbelstenen tegelijk.", "2.  Per worp moet je minimaal één dobbelsteen wegleggen, totdat je alle dobbelstenen hebt weggelegd. Je kan dus maximaal zes keer gooien.", "3.  Het doel is om ofwel het aantal ogen boven de 30 te krijgen, ofwel het aantal ogen onder de 10 te krijgen.", "I.  Als je onder de 10 ogen hebt gehaald, dan krijgt elke speler er 10 strepen bij;", "II. Als je boven de 30 hebt gehaald, mag je nogmaals gooien om streepjes te sparen voor de speler voor jou;", "i.  De speler pakt opnieuw alle dobbelstenen. Hij/zij gaat dan het aantal ogen boven de 30 sparen. De speler voor hem/haar heeft nu al dat aantal ogen boven de 30 als streepjes erbij gekregen.", "Voorbeeld: Speler A gooit 34 ogen. Hij mag nu 4en sparen voor Speler B. Speler B heeft al 4 streepjes.", "ii. Je mag doorsparen totdat je het aantal ogen, dat je spaart, niet meer gooit.", "iii. Bij elke dobbelsteen met het juiste aantal ogen, krijgt de speler voor je streepjes erbij. De regel is: voor elke extra dobbelsteen verdubbelt het aantal streepjes. Dit staat los van de eerste streepjes die zijn verdiend.", "Voorbeeld: Speler A uit het vorige voorbeeld heeft vier [4] gegooid. Voor speler B heeft hij dus 4x2x2x2 = 32 streepjes verdient. Hier komen de eerste vier streepjes (regel 3.II.i) nog boven op, dus (32 + 4 =) 36 streepjes.", "III. Wanneer je tussen de 10 en de 30 ogen gooit, krijg je zelf het verschil met 30 in streepjes erbij.", "Heeft een speler precies 10, dan hoeft die speler niet te drinken, maar krijgen de andere spelers er geen 10 streepjes bij.", "Voorbeeld: Speler C heeft 24 gegooid. Hij krijgt nu (30 - 24 =) zes streepjes erbij.", "4.  De beurt schuift nu op naar de speler links."]}, {"kop": "Verloop van het spel", "regels": ["1.  Streepjes mag je alleen maar per 5 streepjes of meervoud daarvan wegwerken. Eén streepje is één slok.", "2.  Als je aan de beurt bent, moet jouw streepjestotaal 10 of lager zijn. Als je boven de 10 zit, krijg je 15 streepjes erbij.", "N.B. De streepjes dienen dus allemaal genoteerd te worden en dienen goed bijgehouden te worden door een centraal persoon. Anders wordt het te onoverzichtelijk."]}, {"kop": "Variërende regels (zelf af te spreken)", "regels": ["1.  De streepjes die je spaart als je boven de 30 hebt gegooid, verdubbelen zich niet, maar tellen op.", "Voorbeeld: Speler B, uit de eerste twee voorbeelden, heeft nu geen 36 streepjes, maar (eerste)4 + 4+4+4+4 = 20 streepjes.", "2.  Als de ogen gaat sparen, mag je drie keer gooien, ongeacht of je de juiste dobbelstenen gooit.", "3.  Als je aan de beurt bent moet je streepjestotaal 15 of lager zijn (in plaats van 10). Heeft een speler meer streepjes, dan krijg hij/zij er 10 streepjes bij (in plaats van 15)."]}], "pullen": [1, 1, 1]}, {"title": "Jessen", "spelers": null, "benodigdheden": ["Eén dobbelsteen per speler, die duidelijk te onderscheiden is van de andere dobbelstenen", "Dienblad"], "glas": "8 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  Elke speler heeft een eigen, herkenbare, dobbelsteen. Iedereen gooit zijn/haar dobbelsteen op hetzelfde moment in het dienblad.", "2.  Je moet drinken wanneer:", "I.  Jouw dobbelsteen het laagste aantal ogen heeft, één slok;", "II. Indien twee spelers allebei dezelfde worp hebben, moeten beide twee éxtra slokken nemen;", "III. Als drie of meer spelers dezelfde worp hebben, moet iedereen een muur aanraken. De laatste speler moet een adtje trekken;", "IV. Als er een [6] wordt gegooid, moet iedereen per [6] één keer ‘Jes’ roepen. De laatste speler moet één slok drinken;", "V.  Als er driemaal of vaker een [6] wordt gegooid, moet iedereen ‘Suk a kok’ roepen. De laatste speler moet een half adtje trekken;", "VI. Als er drie opeenvolgende dobbelstenen (straat) liggen, moet de speler van de middelste dobbelsteen één slok drinken;", "Voorbeeld: Speler A gooit [6], Speler B gooit [4], Speler C gooit [5]. Speler C moet nu één slok drinken.", "VII. Bij grotere straten dan drie, wordt de straat opgedeeld in straten van drie. De middelsten moeten drinken.", "Voorbeeld: Naast de worpen van het vorige voorbeeld gooit Speler D [3]. Nu moeten Speler C (straat van [4] tot en met [6]) en Speler D (straat van [3] tot en met [5]) één slok drinken."]}, {"kop": "Regels met betrekking tot het spel verloop", "regels": ["1.  Ongeoorloofde toiletbezoeken worden bestraft met het verplicht uittrekken van één kledingstuk, gedurende minimaal één uur.", "I.  Alle sokken en schoenen tellen als geheel als één kledingstuk;", "II. En bril is geen kledingstuk;", "III. De ruimte verlaten, om welke reden dan ook, geldt als toiletbezoek, met uitzondering van bier halen.", "2.  Wanneer je de verkeerde dobbelsteen oppakt, moet je één slok drinken.", "3.  Wanneer iemand nog niet heeft meegespeeld en mee wilt spelen, mag de rest een persoonlijke regel verzinnen. Deze regel wordt bekrachtigd door een high five.", "I.  Als een persoonlijke regel wordt overtreden, dan moet deze speler de tegenoverliggende muren van de ruimte waarin Jessen wordt gespeeld aanraken.", "4.  Als iemand vrijwillig een adtje trekt, dan mag deze speler de tafel verplaatsen."]}], "pullen": [1, 1, 1]}, {"title": "Liar’s Dice", "spelers": null, "benodigdheden": ["Vijf dobbelstenen per speler", "Eén ondoorzichtige beker per speler"], "glas": "8 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  Aan het begin van elke ronde gooit elke speler al zijn dobbelstenen in de beker, zodat de anderen jouw dobbelstenen niet kunnen zien.", "2.  Elke speler bekijkt zijn dobbelstenen. Als er twee dobbelstenen op elkaar liggen, mag die speler met zijn beker heen en weer schudden, zodat er geen dobbelstenen meer op elkaar liggen.", "N.B. Hierna wordt er niet meer met de dobbelstenen gegooid!", "3.  Eén speler begint met bieden. Hierbij geeft hij aan hoeveel dobbelstenen van een bepaald aantal ogen op tafel ligt.", "Let op! Dit bod geldt voor alle dobbelstenen van alle spelers.", "Let op! Als er in het eerste bod niet op 1en wordt geboden, tellen 1en als jokers.", "Voorbeeld: Speler A begint de bieding met 'zes 2en.’", "4.  De beurt verschuift met de klok mee. De volgende speler kan:", "I.  De bieding doorzetten:", "De speler moet ofwel het aantal van geboden dobbelstenen verhogen, ofwel de waarde van de dobbelsteen verhogen;", "Voorbeeld: In hetzelfde spel als het vorige voorbeeld, is nu Speler B aan de beurt. Hij biedt ‘zeven 2en’. Daarna is Speler C aan de beurt. Zij biedt ‘zes 3en.’", "II. Zijn/haar voorganger niet geloven en de beker trekken:", "Op dat moment moet iedereen zijn beker trekken en worden de dobbelstenen geteld.", "5.  Als iemand zijn voorganger niet gelooft, zijn er twee mogelijkheden:", "I.  Er ligt evenveel of meer dan geboden op tafel. De speler, die de beker heeft getrokken, heeft verloren.", "Voorbeeld: In hetzelfde spel als de vorige voorbeelden, heeft Speler C ‘zes 3en’ geboden. Speler D gelooft haar niet. Iedereen trekt zijn/haar beker. Er ligt op tafel: 4x[1]2x[2], 5x[3], 4x[4], 2x[5], 3x[6]. Speler D heeft verloren, er liggen negen (= meer dan zes) 3en op tafel, met de vier 1en als jokers meegeteld.", "II. Er ligt minder dan geboden op tafel. De speler, die als laatste heeft geboden, heeft verloren.", "Voorbeeld: In hetzelfde spel als de vorige voorbeelden, heeft Speler C ‘zes 3en’ geboden. Speler D gelooft haar niet. Maar nu ligt op tafel: 1x[1], 5x[2], 4x[3], 3x[4], 2x[5], 5x[6]. Speler C heeft verloren, er liggen minder dan zes 3en op tafel.", "6.  De verliezende speler moet een half glas drinken en mag de volgende ronde beginnen met bieden."]}, {"kop": "Variërende regels (zelf af te spreken)", "regels": ["1.  Elke keer als een speler een ronde verliest, verliest die speler ook een dobbelsteen. Deze dobbelsteen wordt ook niet meer geteld bij het totaal dat op tafel ligt. De laatste speler die nog dobbelstenen overhoudt, heeft het spel gewonnen.", "I.  Eventueel: Als een speler al zijn/haar dobbelstenen kwijt is, moet hij/zij een adtje trekken.", "2.  Als een speler zijn/haar voorganger niet gelooft en op tafel ligt exact het bod van zijn/haar voorganger moet hij/zij dubbel drinken.", "3.  Als iemand vijf dezelfde dobbelstenen (‘jackpot’) heeft gegooid, mag hij/zij dit kenbaar maken. Er zijn dan twee opties:", "I.  Hij/zij wordt niet door iemand uitgedaagd. Iedereen, behalve de speler, die de jackpot claimde, moet een adtje trekken;", "II. Een andere speler trekt een half adtje en daagt de speler uit:", "i.  De uitdager verliest (er liggen vijf dezelfde stenen):", "Iedereen moet een adtje. De uitdager moet een half adtje trekken;", "ii. De uitdager wint (er liggen geen vijf dezelfde stenen):", "De speler, die jackpot claimde, moet een adtje trekken."]}], "pullen": [0, 1, 0]}, {"title": "Beerpong", "spelers": "2 – 4", "benodigdheden": ["Beerpong tafel, cantustafel of een andere tafel", "20 plastic bekers, bij voorkeur Red cups", "1 of 2 glazen met water (om balletjes te spoelen)", "2 pingpongballetjes"], "glas": "1/10 deel van een pitcher", "secties": [{"kop": "Spelregels", "regels": ["1.  Er worden twee teams gevormd, die de bekers van de tegenpartij moeten wegspelen. Een beker wordt weggespeeld als de pingpongbal in een beker van de tegenpartij wordt gegooid.", "2.  De elleboog van de speler, die werpt, moet achter de achterste rand van de tafel blijven.", "3.  Als een pingpongbal in de beker wordt gegooid, moet deze door de tegenpartij worden leeggedronken.", "4.  Een team heeft verloren als al hun bekers zijn weggespeeld.", "5.  Wanneer een team heeft verloren, moet dit team ook alle overgebleven bekers van de tegenpartij opdrinken."]}, {"kop": "Variërende regels (zelf af te spreken)", "regels": ["1.  Herschikken van bekers:", "I.  Het team mag de bekers van de tegenstanders één of twee keer herschikken, zoals zij willen;", "II. Het team mag zijn eigen beker een of twee keer herschikken;", "III. Het team mag zijn tegenstanders vragen of zij de bekers willen herschikken.", "2.  Wanneer met een stuiter wordt gegooid, mag de bal na de stuit worden weggevangen of worden weggeslagen.", "3.  Als de bal met een stuiter raak wordt gegooid, moeten er twee bekers worden gedronken.", "4.  Als een worp van een team raak is, krijgt dat team de pingpongbal weer terug.", "5.  Als de eerste worp van een team raak is, mag de beker nog niet worden opgedronken. Wanneer de tweede worp van het team in dezelfde beker wordt gegooid, dan drinkt het andere team alle aangrenzende bekers leeg, of heeft het andere team automatisch verloren.", "6.  Als de bal van een bekertje terug stuitert over de tafel naar de helft van het team, dat de bal heeft gegooid, mag dit team de bal pakken en nogmaals gooien, eventueel door middel van een trickshot."]}], "pullen": [1, 1, 0]}, {"title": "Stack Cup", "spelers": null, "benodigdheden": ["Twee pingpongballetjes", "(bij meer dan 5 spelers kan je meer balletjes gebruiken)", "Heel veel bekers, bij voorkeur (rode) Solo Cups"], "glas": "Niet van toepassing", "secties": [{"kop": "Voorbereiding", "regels": ["1.  Vul alle bekers op één na voor een kwart/een bodempje en vul de laatste beker volledig. Plaats deze in een cirkel op het midden van de tafel, met de volle beker in het midden (zie afbeelding)."]}, {"kop": "Spelregels", "regels": ["1.  De twee beginnende spelers (of bij meer balletjes, meer spelers), horen tegenover elkaar te staan.", "2.  Aan het begin nemen ze een beker en drinken deze leeg.", "3.  De spelers proberen de pingpongbal met één stuit in de door hun zojuist leeggedronken beker te krijgen.", "N.B. Gooit een speler de bal in een gevulde beker? Dan moet de speler deze eerst leegdrinken.", "I.  Lukt dit in één keer, dan mag deze speler de beker óf aan de speler links van hem/haar óf aan een willekeurige speler doorgeven, behalve direct rechts van hem/haar of spelers die bezig zijn;", "Hint: Zet de beker dan rechts van een andere speler, die aan de beurt is!", "II. Lukt dit, maar niet in één keer, dan moet de speler de beker met bal naar links doorgeven.", "4.  Gooit een speler de pingpongbal in de beker, terwijl de speler direct links daarvan ook bezig is met spelen, dan moet de speler de beker in de beker van de speler links van hem/haar zetten. De speler links heeft verloren.", "5.  De verliezer geeft de stapel door naar links, drinkt één van de gevulde bekers leeg en probeert de bal met een stuit in de nieuwe beker te gooien.", "Let op! De andere speler mag al meteen beginnen!", "6.  Het spel is afgelopen als alle bekers zijn leeggedronken."]}, {"kop": "Variërende regel (zelf af te spreken)", "regels": ["1.  De lege bekers, waarmee wordt gespeeld, moet tegen de groep volle bekers worden gezet."]}], "pullen": [1, 1, 0]}, {"title": "21’en", "spelers": null, "benodigdheden": ["Niet van toepassing"], "glas": "8 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  Bij dit spel moeten de spelers om beurten tot 21 tellen.", "2.  Wanneer een speler aan de beurt is, kan hij/zij:", "I.  Eén getal noemen, de beurt gaat in dezelfde richting door;", "II. Twee getallen noemen, dan schuift de beurt in de tegenovergestelde richting door;", "III. Drie getallen noemen, dan schuift de beurt in dezelfde richting door, maar wordt er één speler overgeslagen.", "3.  De beginnende speler noemt één, twee of drie getallen, gevolgd dor de richting waarmee het spel begint.", "Voorbeeld: Speler A begint de ronde en zegt: ‘1, 2, 3, rechts.’ De richting is nu rechtsom en er wordt één speler overgeslagen.", "4.  Een speler moet één slok drinken, als:", "I.  Hij/zij het verkeerde getal zegt;", "II. Hij/zij iets zegt, terwijl hij/zij niet aan de beurt is.", "5.  Wanneer de 21 is bereikt, is de ronde afgelopen. De speler, die 21 moet zeggen, heeft verloren en moet een half adtje trekken.", "6.  Alvorens een nieuwe ronde wordt begonnen, moet de verliezer een nieuwe (blijvende) regel voor het tellen bedenken.", "Voorbeeld: Speler B heeft verloren en verzint de regel “de ‘7’ en de ‘17’ worden omgewisseld.” Nu moet elke speler in plaats van het getal 7, het getal 17 noemen en vice versa."]}, {"kop": "Variërende regel (zelf af te spreken)", "regels": ["1.  De verliezer moet eerst daadwerkelijk ‘21’ zeggen, voordat hij/zij drinkt. Doet hij/zij dat niet, moet hij/zij opnieuw drinken."]}], "pullen": [0, 1, 0]}, {"title": "Duikboten", "spelers": null, "benodigdheden": ["Een pitcher met bier", "Een extra glas"], "glas": "8 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  Het extra glas wordt voorzichtig in de pitcher gedaan, zodat deze blijft drijven.", "2.  Als een speler aan de beurt is, moet hij/zij uit zijn eigen glas bier schenken in het glas, dat in de pitcher drijft.", "I.  De speler mag maar maximaal één keer schenken, dus wanneer er even geen bier uit zijn/haar glas komt, is zijn/haar beurt afgelopen.", "II. Er moet minimaal één druppel in het glas worden geschonken;", "III. De speler mag zelf bepalen hoeveel bier hij/zij in het drijvende glas schenkt;", "IV. Wanneer je naast het drijvende glas schenkt, moet je een slok uit je eigen glas nemen en alsnog proberen bier in het drijvende glas te schenken.", "3.  De beurt schuift met de klok mee door.", "4.  Wanneer het drijvende glas zinkt, moet de speler, die het laatste heeft geschonken, het gezonken glas uit de pitcher halen en dit glas leegdrinken.", "5.  De verliezende speler mag de volgende ronde beginnen."]}], "pullen": [1, 1, 0]}, {"title": "Handje klap", "spelers": null, "benodigdheden": ["Een (ronde) tafel."], "glas": "8 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  Alle spelers laten hun armen kruisen met die van de buurman. Jouw linkerarm gaat onderlangs, jouw rechterarm kruist bovenlangs.", "2.  Een speler begint door te zeggen in welke richting het spel wordt gespeeld en slaat dan met één van zijn twee handen eenmaal, tweemaal of driemaal op tafel.", "3.  De speler die aan de beurt is, heeft de keuze:", "I.  Eénmaal te slaan, het spel gaat in dezelfde richting door;", "II. Tweemaal te slaan, het spel gaat in de tegenovergestelde richting door;", "III. Driemaal te slaan, het spel gaat in dezelfde richting door, maar de volgende hand wordt overgeslagen.", "4.  De speler, die als eerste een fout maakt, heeft verloren. Fouten kunnen zijn:", "I.  Niet slaan, wanneer hij/zij wel aan de beurt is;", "II. Met de hand slaan, terwijl hij/zij niet aan de beurt was.", "5.  De verliezer moet een slok nemen en mag de volgende ronde beginnen."]}], "pullen": [0, 1, 0]}, {"title": "Kneiteren", "spelers": null, "benodigdheden": ["Een extra glas", "Een munt, bij voorkeur 5 cent"], "glas": "Niet van toepassing", "secties": [{"kop": "Spelregels", "regels": ["1.  De oudste speler is aan het begin van het spel hoofdkneiter en mag de functies verdelen. De bestaande functies zijn:", "I.  Bierkneiter: deze speler moet gedurende zijn functie bier voor de andere spelers halen, indien dat wordt gevraagd;", "II. Muntkneiter: deze speler moet gedurende zijn functie de munt halen als deze weg stuitert. De andere spelers mogen de munt niet aanraken, tenzij het zijn/haar beurt is;", "III. Glazenkneiter: deze speler mag aan het begin van de ronde en tijdens de ronde de glazen (ook de volle glazen van de spelers en extra glazen) neerzetten naar eigen willekeur. Hij/zij mag ook bepalen in welk glas de munt moet komen.", "2.  De spelers proberen om beurten (met de klok mee) de munt via een stuiter op de tafel in het juiste glas te krijgen/kneiteren.", "I.  Stuitert de munt in een vol glas, dan moet de speler, die de munt heeft gegooid, dit glas leegdrinken.", "3.  Wanneer een speler dit gelukt is, is hij/zij de hoofdkneiter en mag de functies naar eigen wens (her)verdelen."]}, {"kop": "Variërende regel (zelf af te spreken)", "regels": ["1.  Wanneer een speler het glas mist, moet hij/zij één slok drinken. Er zitten dan 8 slokken in een glas."]}], "pullen": [0, 1, 0]}, {"title": "Tafeltennis", "spelers": null, "benodigdheden": ["Niet van toepassing"], "glas": "8 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  De speler die begint, mag serveren. Dit doe hij/zij door met een van zijn/haar handen, met de handpalm naar boven een omhoogslaande beweging te maken (alsof de speler een pingpongballetje opgooit). Daarna maakt de serverende speler of met de vlakke rechterhand naar links of met de vlakke linkerhand naar rechts een slaande beweging (alsof de speler de bal doorspeelt). Dit is de spelrichting.", "2.  De volgende speler is de speler waar de bal naartoe is geslagen.", "Voorbeeld: Speler A serveert en slaat met zijn linkerhand naar rechts. Speler B zit rechts van Speler A en is nu aan de beurt.", "3.  De volgende speler kan nu vier dingen doen:", "I.  Een slaande beweging maken zoals ook de serveerder (met rechts naar links of andersom). Het spel gaat in dezelfde richting door;", "II. Eén elleboog op tafel zetten. Het spel gaat nu door in tegenovergestelde richting;", "Let op! Het is belangrijk welke elleboog je op tafel zet. Als de bal van links komt, moet je je rechterelleboog op tafel zetten en vice versa.", "III. Twee vuisten op tafel slaan. Het spel gaat nu door in dezelfde richting, maar de volgende speler wordt overgeslagen;", "IV. Twee ellebogen op tafel zetten. Het spel gaat nu door in tegenovergestelde richting én er wordt een speler overgeslagen.", "4.  De verliezer is de speler die als eerste een fout maakt, dat kan door:", "I.  Een spelactie te maken, wanneer die speler niet aan de beurt is;", "II. Geen spelactie te maken, wanneer die speler wel aan de beurt is;", "III. Voor de derde keer achtereen dezelfde spelactie maken. (Elke spelactie kan in een rally dus hooguit tweemaal achter elkaar worden gemaakt);", "IV. Een spelactie verkeerd uitvoeren.", "5.  De verliezer moet een slok/half adtje drinken en mag daarna serveren (zie regel 1.)."]}], "pullen": [0, 1, 0]}, {"title": "Vinger op ‘t Glaasje", "spelers": null, "benodigdheden": ["Glas"], "glas": "Niet van toepassing", "secties": [{"kop": "Spelregels", "regels": ["1.  Er wordt een glas op de tafel gezet en (half) gevuld met bier.", "2.  Iedereen legt een vinger op het glas. De speler, die begint, zegt hoeveel mensen zijn/haar vinger op het glas houden. Op het moment dat de speler dit zegt, halen de andere spelers hun vinger van het glaasje of laten ze hun vinger op het glaasje.", "I.  Wanneer de speler het juiste aantal vingers heeft genoemd, is hij/zij klaar en speelt hij/zij niet meer mee met de ronde. De beurt verschuift dan met de klok mee;", "II. Heeft de speler het aantal vingers op het glas fout, dan speelt hij/zij nog steeds mee. De beurt verschuift met de klok mee.", "3.  Tijdens het spel zullen spelers, die het goed hadden, afvallen, totdat er nog maar één speler over is (die dus nooit het aantal vingers goed heeft gehad). Deze speler is de verliezer en moet het glas leegdrinken.", "4.  De verliezer vult het glas en mag de volgende ronde beginnen."]}, {"kop": "Variatie", "regels": ["1.  Dit spel staat ook wel bekend als Vijven. Dan heb je geen glas nodig en raad je het aantal vingers. De speler aan de beurt noemt een vijftal op. Terwijl hij/zij dit vijftal noemt, maken alle spelers een vuist (0 vingers) of een platte/open hand (5 vingers). Overige regels zijn hetzelfde."]}], "pullen": [1, 1, 0]}, {"title": "Hazen", "spelers": null, "benodigdheden": ["Eén pitcher"], "glas": "56 slokken", "secties": [{"kop": "Spelregels", "regels": ["1.  Er wordt een pitcher gehaald en deze start bij één van de spelers rondom de tafel.", "2.  De speler die de pitcher in handen heeft mag zelf bepalen hoeveel hij uit deze pitcher drinkt.", "3.  De beurt van een speler bestaat uit het onafgebroken drinken uit de pitcher, waarmee wordt bedoeld dat de speler zijn lippen niet van de pitcher mag halen en dat hij niet mag pauzeren met de pitcher aan zijn lippen.", "4.  Zodra de speler met de pitcher in de handen stopt met drinken uit de pitcher geeft hij deze door aan de speler links van hem.", "5.  Het drinken uit de pitcher herhaalt zich.", "6.  De speler die de pitcher leegdrinkt naait daarmee de speler rechts van hem.", "7.  De speler rechts van degene die de pitcher leegdrinkt haalt een nieuwe pitcher.", "2."]}], "pullen": [1, 0]}];
var VOORWOORD_DATA=["Beste lezer,", "Voor u ligt alweer de tweede uitgave van JEROENs BIERSPEL BIJBEL, nu omgetoverd tot JEROEN en KEVINs BIERSPELBIJBEL. Dit boekwerk is een verzameling van spelregels van de bierspellen die door de leden van SV KoKo worden gespeeld. Een (groot) deel van de spellen is bij de meeste leden wel bekend, een deel echter niet. Dit boekje is niet alleen opgesteld om leden kennis te laten maken met nieuwe bierspellen, maar ook om minder gespeelde spellen van uitsterven te behoeden.", "Speciale dank bij het schrijven van dit boekwerk gaat uit naar dhr. Jeroen Velzing wie veel moeite heeft gestoken in het uitbrengen van een eerste versie van deze heilige bijbel. Vanuit de heilige basis van de eerste versie zijn er aanpassingen gedaan aan de bijbel en is er een kleine uitbreiding bijgekomen. Er is in deze versie bewust voor gekozen om de bijbel toch compact te houden en tevens geen spel te schrappen om kennis en kunde met betrekking tot de verscheidenheid aan bierspellen binnen de vereniging te behouden.", "Ook in JEROEN en KEVINs BIERSPELBIJBEL staan de spellen weer logisch gesorteerd aan de hand van de spelbenodigdheden. Alle spellen zijn op uniforme en begrijpelijke wijze uitgewerkt, met eventueel voorbeelden en illustraties ter verheldering. Elk spel heeft ook een gemiddelde aanduiding van de mate waarin men bier dient te drinken bij dit spel. Dit is terug te zien aan het aantal gevulde pullen vermeld bij het spel op een schaal van 1,0 tot en met 3,0 pullen. Achter in het boekje staat een compacte tabel met alle spellen, voorzien van paginanummers. De spellen zijn hier gesorteerd op de mate van drinken en de complexiteit van de spelregels en -tactieken.", "Moge deze bijbel ook in uw handen heilig blijven!", "Kevin Bruggeman", "Betrokken lid der SV KoKo"];
